"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81530"],{93173(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.banca_duplicada_na_etapa","status":422,"titulo":"O mesmo tipo de banca foi requerido duas vezes na etapa"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.banca_duplicada_na_etapa","requisitos":[],"oQueAconteceu":["Uma das etapas do pedido de defini\xe7\xe3o de etapas\\n(`PUT .../processos-seletivos/{id}/etapas`) declarou, em `bancas`, o mesmo tipo de\\nbanca mais de uma vez: o c\xf3digo do tipo \xe9 que identifica a banca na etapa, e a\\nrepeti\xe7\xe3o \xe9 detectada pelo c\xf3digo do tipo de banca resolvido no cadastro.","A recusa n\xe3o \xe9 acumulada com as demais: vem depois da confer\xeancia da forma, do\\ncar\xe1ter e da avalia\xe7\xe3o de todas as etapas, e \xe9 conferida etapa por etapa, na ordem\\ndo pedido, depois da declara\xe7\xe3o dos atos e do per\xedodo de cada etapa e depois de\\ntodos os tipos de banca da etapa terem sido encontrados no cadastro\\n([`tipo_banca_nao_encontrado_ou_inativo`](/erros/uniplus.selecao.etapa_processo.tipo_banca_nao_encontrado_ou_inativo)).\\nA primeira etapa com problema interrompe a confer\xeancia, e a resposta traz s\xf3 esta\\nrecusa, sem indicar qual \xe9 a etapa. Nada \xe9 gravado."],"comoResolver":["Deixe cada tipo de banca uma \xfanica vez na etapa e reenvie a defini\xe7\xe3o. Se o\\npedido tem v\xe1rias etapas com bancas, confira todas, porque as seguintes s\xf3 s\xe3o\\nconferidas depois que esta for corrigida."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);